INSERT INTO brands ("id", "name", "icon", "navColor", "soul", "adStyle", "hashtags") VALUES ('cf', '巧福健康家電', '🏠', 'brand_chiaofu', '溫暖居家、守護家人健康、實用親切、台灣品牌精神。語氣親切有溫度，強調讓每個家庭感受被照顧的生活升級感。廣告切入點：家人痛點（冬天怕冷/夏天悶熱/蚊蟲困擾/腰痠背痛）→ 巧福給你最省力的解法。', '溫暖生活感、家人守護、療癒放鬆、痛點直擊', '#居家健康 #巧福 #台灣品牌 #遠紅外線 #居家療癒');
INSERT INTO brands ("id", "name", "icon", "navColor", "soul", "adStyle", "hashtags") VALUES ('ww', '旺味米香腸', '🌾', 'brand_ww', '全台首創米香腸，傳承阿公「好的東西要守住」家訓。台灣認證豬肉＋台灣Q彈長糯米，黃金比例3:7手工灌製。', '台灣古早味、手工真材實料、烤肉聚餐場景、家鄉情感、中秋露營', '#旺味米香腸 #米香腸 #台灣豬 #手工香腸 #中秋烤肉 #露營美食 #古早味');
INSERT INTO brands ("id", "name", "icon", "navColor", "soul", "adStyle", "hashtags") VALUES ('ly', '琉宇醬選', '🫙', 'brand_ly', '琉宇醬選主理頂級進口醬料，旗下兩大系列：好滋好滋零食＋PASSERI頂級松露。', '精緻質感、食材溯源、料理升級、零食健康感', '#琉宇醬選 #好滋好滋 #PASSERI #松露 #頂級醬料');
INSERT INTO brands ("id", "name", "icon", "navColor", "soul", "adStyle", "hashtags") VALUES ('moz', 'MOZ瑞典駝鹿', '🦌', 'brand_moz', '瑞典駝鹿DNA，用北歐色彩與趣味設計讓日常更輕鬆愉快。不將就、敢玩色、輕鬆過每一天。主力品項：洞洞鞋、雲朵包，主打外國模特兒呈現國際感。', '北歐輕鬆感、顏值日常、戶外露營風、多色搭配、活潑年輕、歐美MD', '#MOZ瑞典駝鹿 #北歐設計 #洞洞鞋 #雲朵包 #北歐風');
INSERT INTO brands ("id", "name", "icon", "navColor", "soul", "adStyle", "hashtags") VALUES ('ka', '空瑪那', '🎯', 'brand_ka_yoga', '空瑪那是台灣頂尖身心靈國際學院，由宸甄老師創立，擁有20年以上教學經驗。與日月潭涵碧樓、台大醫院、自然科學博物館合作，日本觀光大使川口春奈親身體驗頌缽。不賣商品，賣的是讓生命慢下來的智慧。文案強調療癒感受、名人背書、國際認證。', '療癒禪意、國際專業、身心靈覺醒、名人背書、課程體驗感受', '#空瑪那 #頌缽療癒 #瑜珈師資 #冥想 #身心靈 #宸甄老師');
INSERT INTO brands ("id", "name", "icon", "navColor", "soul", "adStyle", "hashtags") VALUES ('la', 'LACEZ', '💎', 'brand_lacez', 'LACEZ是台灣MIT內衣品牌，工廠直接賣給消費者，連競爭對手大成內衣、玉如阿姨都是我們代工。精品質感不精品價格，讓每個女生都能穿到真正好的內衣，不花冤枉錢。強調閨蜜感、真實穿感、MIT驕傲。', '閨蜜親切、精品感平價、MIT驕傲、穿出自信、真實穿感、蕾絲美學', '#LACEZ #台灣MIT #好內衣不貴 #無鋼圈 #集中內衣 #工廠直售');
INSERT INTO brands ("id", "name", "icon", "navColor", "soul", "adStyle", "hashtags") VALUES ('ra', 'RADESIGN', '🏷️', 'brand_radesign', 'RADESIGN專營正版品牌鞋Outlet，百分百原廠授權，不是仿冒不是瑕疵，只是品牌出清。讓你穿到真正的好鞋，價格讓人驚喜。主攻蝦皮市場，用低毛利搶佔市佔。', '直白促銷、正版保證、超值撿漏、蝦皮熱銷、限量稀缺感', '#RADESIGN #正版outlet #品牌鞋特賣 #蝦皮 #運動鞋');
INSERT INTO brands ("id", "name", "icon", "navColor", "soul", "adStyle", "hashtags") VALUES ('flm', '香港福臨門', '🏮', 'brand_flm', '1948年創立於香港灣仔，近八十載粵菜傳承。米其林一星連續七年、富豪飯堂、中餐少林寺。每日新鮮食材、傳統手工烹製、百道工序成就每一味。室內無窗，完整保留正統中式大酒樓氣派。招牌菜：當紅炸子雞、脆皮烤乳豬、瑤柱荷葉飯、蛋黃八寶鴨。', '高端粵菜質感、傳承匠心、米其林星級、香港在地情懷、簡體中文為主（小紅書/抖音）、港味文案風格、強調手工工序複雜、不涉及家族人物歷史、避免台灣慣用語', '#福臨門 #FookLamMoon #香港美食 #米其林 #粵菜 #富豪飯堂 #香港必吃 #灣仔美食 #港式粵菜');
INSERT INTO brands ("id", "name", "icon", "navColor", "soul", "adStyle", "hashtags") VALUES ('ever_7011', 'Every Hay', '🏷️', 'brand_ever_7011', 'Every Hay 是來自美國華盛頓州的精選提摩西草品牌,專為兔子、龍貓、天竺鼠等小動物挑選最頂級的第一次收割(1st Cutting)乾草。纖維值高達 38%、葉莖比例平均、人工挑選低粉塵處理,用 2025 年最新收割批次,讓每一份草都保持翠綠色澤與獨特天然草香。從美國農場直送香港,主打「讓小動物一試便愛上」的高適口性,品牌精神 — Your Every Hay Day,把每一天都變成毛孩值得期待的草日。香港總代理 Moko Moko x 香港寵物節 2026 重磅登場。', '自然清新、寵物溫馨、美式農場質感、療癒草香、毛孩主人共鳴、輕奢寵物日常', '#EveryHay #提摩西草 #美國提摩西草 #1stCutting #兔兔零食 #龍貓乾草 #天竺鼠 #毛孩日常 #香港寵物節2026 #MokoMoko #HKPetShow2026 #寵物用品 #高纖維乾草 #YourEveryHayDay');
INSERT INTO brands ("id", "name", "icon", "navColor", "soul", "adStyle", "hashtags") VALUES ('protex', 'PROTEX', '🏷️', 'coral', '專業防熊、戶外安全守護,日本規格 2.00% 辣椒素,為登山露營者爭取逃生時間', '專業權威、安全至上、簡潔有力,用數據建立可信度', '#防熊噴霧 #戶外安全 #登山裝備 #露營必備 #日本規格 #BearSpray #OutdoorSafety #PROTEX');
