INSERT INTO brand_packs ("pack_key", "label", "matchKeywords", "primary_color", "secondary_palette", "typography", "photography_style", "mood", "decorative_elements", "scenes", "composition_habit", "avoid", "is_active", "updated_at", "notes") VALUES ('chiaofu', '巧福 CHIAO FU', 'chiaofu,chiao fu,巧福,chiao', 'deep forest green #3D5A3F (used for headlines, footer bands, accent strokes, brand circular logo)', 'warm cream #F5EFE5, soft beige #E8DCC8, dusty terracotta #C49B7E, retro powder blue #A8C5D0', 'Traditional Chinese display headline in 明朝體 / Mincho Serif (large, refined, slightly squared); body copy in clean thin Sans (思源黑體 light); brand signature is the round "CHIAO FU" white-on-green logo', 'warm natural daylight from upper-left window, 4500-5500K, soft shadows, slight matte film texture (not glossy)', 'nostalgic-modern Taiwan, Showa-era Taiwan domestic life, "old-but-renewed" feeling, quiet and gentle', 'thin horizontal divider lines (1-2px solid green), the round "CHIAO FU" logo mark centered at bottom on green band, modest paper grain texture overlay', 'warm Taiwan domestic atmosphere with quiet contemplative feel, gentle morning or afternoon light, soft shadows, lived-in home or porch setting — the specific era, furniture style, decor, and scene props are intentionally left to the regional flavor layer to determine', 'large generous negative space (40-50%), bottom solid green band as footer with white round logo, headline text in deep forest green', 'neon colors, electric zapper imagery (purple-light bug zappers), buzzing/electricity FX, sharp tech aesthetics, cluttered layouts, glossy plastic feel, anything that looks like an industrial pesticide product. Note: Suction-type mosquito trap (UC-700/800LED/850LED) is silent airflow-based — NOT electric zapper.', 1, '2026-04-25T11:21:03.524Z', '健康家電 - 捕蚊燈是吸入式不是電擊式 / 復古電風');
INSERT INTO brand_packs ("pack_key", "label", "matchKeywords", "primary_color", "secondary_palette", "typography", "photography_style", "mood", "decorative_elements", "scenes", "composition_habit", "avoid", "is_active", "updated_at", "notes") VALUES ('ka_yoga', '空瑪那 KA 瑜珈', 'ka,空瑪那,kamana,yoga,瑜珈,瑜伽', 'deep pine #4A5D4A', 'soft sage #B5C5A8, accent terracotta #C49B7E, ivory cream #F5EFE8, dusty mauve #B8A8B0', 'refined Serif headline (Cormorant Garamond / Playfair) for English + 思源宋體 Light for Chinese; lots of letter-spacing; calligraphy-feel for accent words', 'soft directional natural daylight from large window, 4500-5500K, low contrast, slight film grain, hands and body in graceful posture', 'contemplative, breathing, slow, Japanese-Korean-Indian wellness fusion (lululemon × Aesop × Ryokan)', 'thin botanical line illustrations (lotus, branches), Sanskrit mantra characters as background watermark texture, wooden mala bead props, ceramic incense holder, single dried flower', 'serene wellness atmosphere with calm contemplative feel, soft natural daylight, graceful body posture, peaceful breathing space — the specific room style, props, and cultural setting are intentionally left to the regional flavor layer to determine', 'vertical breathing space, headline placed mid-upper third, body copy in narrow column, generous 50%+ negative space, asymmetric off-center balance', 'neon, harsh contrast, hyperactive layouts, fitness gym aesthetic (this is yoga not crossfit), overtly sexy poses, kitsch cartoon', 1, '2026-04-25T11:21:03.930Z', '瑜珈課程品牌');
INSERT INTO brand_packs ("pack_key", "label", "matchKeywords", "primary_color", "secondary_palette", "typography", "photography_style", "mood", "decorative_elements", "scenes", "composition_habit", "avoid", "is_active", "updated_at", "notes") VALUES ('lacez', 'LACEZ 法式精品', 'lacez,蕾賜,內衣,lingerie,underwear', 'deep wine #722F2E', 'ivory cream #F5EFE8, champagne nude #DDC4A8, soft taupe #B8A89E, gold accent #C9A665', 'elegant Serif italic for headlines (Cormorant Italic / Playfair); 思源宋體 light for Chinese; refined small caps; lots of letter-spacing', 'soft window-shaded daylight, low contrast, faint film grain, skin-warm tones', 'La Perla / Eres / French boudoir editorial, intimate elegance, NEVER overtly sexual or aggressive', 'silk ribbon graphics, thin gold lines, lace texture overlays, French phrases', 'Parisian apartment morning light, ivory linen drapery, marble dresser, mirror reflections', 'portrait orientation, ample negative space, headline often italicized', 'neon, retro Y2K, masculine sharp tech, comedy/cute, overtly sexual posing', 1, '2026-04-25T11:21:04.389Z', '內衣品牌');
INSERT INTO brand_packs ("pack_key", "label", "matchKeywords", "primary_color", "secondary_palette", "typography", "photography_style", "mood", "decorative_elements", "scenes", "composition_habit", "avoid", "is_active", "updated_at", "notes") VALUES ('radesign', 'RADESIGN 街頭潮', 'radesign,ra design,銳設計,鞋,shoe,sneaker,outlet', 'charcoal black #1A1A1B, accent neon orange #FF6A2A', 'off-white #F0EDE5, asphalt grey #4A4A4D, warm tan #C49B7E, dusty olive #6B7A4E', 'bold condensed Sans Serif (Bebas Neue / Helvetica Inserat / 思源黑體 Heavy); large numerical price/model treatment; underlined category tags', 'high contrast, slightly desaturated, urban concrete textures, golden-hour street light or fluorescent gym light', 'AAPE / HUMAN MADE / New Balance MADE / Carhartt WIP, Tokyo Harajuku street, raw and lived-in', 'tape graphics, dotted reference grids, model number stamps, hand-drawn arrows, retro athletic department badges', 'Tokyo back-alley wet asphalt, vintage gymnasium wood floor, brutalist concrete wall, NY SoHo cobblestone, Taipei night-market texture', 'dynamic asymmetric, often diagonal axis, large model number as decorative element', 'precious-looking, soft floral, romance, marble luxury', 1, '2026-04-25T11:21:04.863Z', '鞋類 / 潮流');
INSERT INTO brand_packs ("pack_key", "label", "matchKeywords", "primary_color", "secondary_palette", "typography", "photography_style", "mood", "decorative_elements", "scenes", "composition_habit", "avoid", "is_active", "updated_at", "notes") VALUES ('ww', '旺味 WANG WEI', 'ww,旺味,wangwei,米香腸,香腸', 'ancient grain rice-yellow #D9B96B (used for headlines, warm background washes, retro label accents)', 'deep green #2C4A2D, BBQ-sauce red #C44329, warm cream #F5EFE0, toasted brown #8B5A2B', 'Traditional Chinese display headline in bold 楷書 / brush-style calligraphy feel (hearty, hand-written warmth); body copy in clean 思源黑體 Regular; price/weight numerals in condensed bold', 'warm appetizing daylight or golden-hour outdoor BBQ light, 3800-4500K, rich saturated food tones, slight steam and sizzle texture, mouth-watering close-ups', 'nostalgic Taiwanese old-time flavor (台灣古早味), hand-made authentic, family BBQ gathering warmth, festive and hearty', 'hand-drawn brush strokes, retro Taiwanese paper-cut motifs, thin red seal-stamp graphics, sizzling-grill steam wisps, woven bamboo basket props', 'traditional Taiwanese kitchen with wooden chopping board and aged teak, or outdoor mid-autumn BBQ grill scene with charcoal glow and family gathering, or rustic market stall with hanging sausages and red lanterns', 'hearty centered composition, food as generous hero filling 50-60%, headline top with brush calligraphy, warm bottom band, appetite-driven framing', 'cold sterile lighting, minimalist Scandinavian emptiness, luxury marble, neon, anything that looks processed/industrial or unappetizing', 1, NULL, '旺味米香腸 - 台灣古早味烤肉聚餐 / SPA 站點爬不到色用色票表');
INSERT INTO brand_packs ("pack_key", "label", "matchKeywords", "primary_color", "secondary_palette", "typography", "photography_style", "mood", "decorative_elements", "scenes", "composition_habit", "avoid", "is_active", "updated_at", "notes") VALUES ('ly', '琉宇醬選 LUYU', 'ly,琉宇,luyu,醬選,passeri', 'truffle black #2C2522 (used for headlines, deep luxury backdrops, refined footer bands)', 'salmon pink #E89B9B, cream beige #F0E5CE, champagne gold #C9A55B, deep olive #4A4530', 'elegant high-contrast Serif headline (Didot / Bodoni feel) for English + 思源宋體 Light for Chinese; generous letter-spacing; refined small caps for category labels', 'dramatic low-key gourmet photography, single warm directional key light, deep shadow falloff, glossy reflections on premium surfaces, Michelin plating aesthetic 3500-4500K', 'refined Italian high-end cuisine, premium gourmet condiment, sophisticated fine-dining elegance, quiet confident luxury', 'thin gold hairlines, embossed-look serif typography, single olive branch or truffle slice prop, subtle marble veining, wax-seal accents', 'dark elegant kitchen with black marble counter and warm pendant light, or fine-dining plated dish on dark slate with truffle shavings, or Italian deli shelf with premium oil bottles in moody light', 'premium portrait orientation, product as luxury hero in lower-center, ample dark negative space, headline in refined serif top, generous 50%+ breathing room', 'bright cheap supermarket feel, cartoon, neon, cluttered busy layouts, garish saturated colors, casual snapshot energy', 1, NULL, '琉宇醬選 - 義式精緻頂級料理 / SPA 站點爬不到色用色票表');
INSERT INTO brand_packs ("pack_key", "label", "matchKeywords", "primary_color", "secondary_palette", "typography", "photography_style", "mood", "decorative_elements", "scenes", "composition_habit", "avoid", "is_active", "updated_at", "notes") VALUES ('moz', 'MOZ 瑞典駝鹿', 'moz,瑞典駝鹿,moose,北歐', 'Nordic blue #4A6B8A (used for headlines, calm background washes, brand accent strokes)', 'camel tan #B89770, spring-bud green #7AA84F, warm cream #F5F0E8, soft slate grey #8A98A5', 'clean modern Sans Serif headline (Futura / Avenir feel) + 思源黑體 Light for Chinese; restrained letter-spacing; minimal geometric category icons', 'bright airy Scandinavian daylight, soft diffused window light 5000-5500K, low contrast, clean uncluttered, gentle natural shadows, fresh and calm', 'Nordic minimalism, moose-character gentle charm, spring-walk freshness, calm functional everyday lifestyle (IKEA × Fjällräven feel)', 'thin geometric line illustrations, subtle moose silhouette motif, clean dotted grids, simple flat icons, light birch-wood textures', 'bright minimal Scandinavian interior with light oak and white walls, or fresh spring forest path with soft morning light, or clean lifestyle flat-lay on pale wood with green sprigs', 'balanced clean composition, generous negative space, product centered or rule-of-thirds, headline calm and unobtrusive, plenty of light breathing room', 'heavy dark luxury, dramatic moody shadows, ornate baroque decoration, neon, cluttered maximalism, hot saturated colors', 1, NULL, 'MOZ 瑞典駝鹿 - 北歐極簡春日漫步 / SPA 站點爬不到色用色票表');
INSERT INTO brand_packs ("pack_key", "label", "matchKeywords", "primary_color", "secondary_palette", "typography", "photography_style", "mood", "decorative_elements", "scenes", "composition_habit", "avoid", "is_active", "updated_at", "notes") VALUES ('flm', '香港福臨門 FOOK LAM MOON', 'flm,福臨門,fook lam moon,fooklammoon', 'China red #B8302E (used for headlines, auspicious accent bands, brand seal mark)', 'bright gold #C9A55B, ink black #1F1A18, warm cream #F2E8D5, deep jade #2C4A3D', 'traditional Chinese display headline in refined 宋體 / Song serif (dignified, slightly squared) + small gold-foil English; classical brush accent for signature words', 'warm luxurious banquet lighting from golden chandeliers 3000-3500K, rich amber glow, dish brightly lit and clearly visible, glossy refined plating, Michelin-star presentation', 'classic Cantonese banquet heritage, traditional refined elegance, Michelin-star fine dining, business-entertainment dining class, prestigious and auspicious', 'thin gold filigree borders, traditional Chinese auspicious motifs (subtle cloud/wave patterns), red-and-gold seal stamps, fine porcelain and ivory-tipped chopstick props', 'Hong Kong top-tier Cantonese banquet hall with white gold-trimmed tablecloth and softly blurred warm amber interior, gold filigree wall panels, red lacquered details, elegant porcelain tea set', 'luxurious centered banquet composition, dish as bright hero, gold-trimmed framing, headline in dignified Song serif top, refined symmetric balance', 'dark moody underexposed dishes, cheap casual diner feel, neon, cartoon, Western fast-food aesthetic, garish clashing colors', 1, NULL, '香港福臨門 - 粵式經典米其林星級 / 福臨門等級宴席');
INSERT INTO brand_packs ("pack_key", "label", "matchKeywords", "primary_color", "secondary_palette", "typography", "photography_style", "mood", "decorative_elements", "scenes", "composition_habit", "avoid", "is_active", "updated_at", "notes") VALUES ('ever_7011', 'Every Hay 寵物草', 'ever_7011,every hay,everyhay,提摩西,牧草,timothy,寵物草', 'hay-cream #C9B584 (used for headlines, warm natural background washes, organic accent strokes)', 'olive green #6B7A4A, warm rice-white #F4EDE0, soft sage #B5C5A8, toasted wheat #D4C088', 'clean friendly Sans Serif headline (rounded, approachable) + 思源黑體 Regular for Chinese; warm natural feel; small leaf/grass motif accents', 'bright natural daylight, soft warm window light 4500-5500K, fresh organic tones, slight natural grain, clean wholesome pet-product photography, appetizing dry-grass texture detail', 'natural botanical wholesomeness, pet-friendly warmth, everyday lifestyle goods, organic Timothy hay freshness, gentle and trustworthy', 'thin organic line illustrations (grass blades, leaves, small animals), kraft-paper texture, natural twine accents, small rabbit/guinea-pig silhouette motifs, dried-grass props', 'bright airy home with light wood and white walls and a small pet corner, or fresh outdoor meadow with golden dry grass and soft sunlight, or clean wholesome flat-lay of hay product on kraft paper with leaf sprigs', 'warm natural composition, product as fresh hero, generous airy negative space, headline friendly and clear at top, organic balanced framing', 'dark luxury, cold sterile clinical feel, neon, harsh tech aesthetic, garish saturated colors, anything that looks chemical/processed', 1, NULL, 'Every Hay 寵物草 - 天然草本提摩西草 / 寵物友善生活雜貨');
