INSERT INTO brand_applications ("id", "status", "submittedAt", "email", "name", "website", "fb", "ig", "xiaohongshu", "douyin", "wechat", "socialOther", "contact", "phone", "story", "values", "competitors", "competitorUrls", "pros", "cons", "misc", "category", "products", "platforms", "price", "audience", "style", "ref", "color", "colorHex", "photoFolder", "videoFolder", "soulBook", "reviewNote", "kolType", "kolUrl1", "kolUrl2", "ownerName", "ownerStory", "ownerTone", "kolGenerated", "kolGenError", "desiredPlan") VALUES ('brand_1775802906944', 'approved', '2026-04-10T06:35:06.944Z', 'misa@owohad.com', 'Every Hay', NULL, NULL, 'https://www.instagram.com/everyhayco?igsh=eGtxcmtxd3Q4NHl6', NULL, NULL, NULL, NULL, '黄思语', '+852 65183318', 'Every Hay 的創立核心源於重塑高端牧草品質與家庭寵物營養的連接，具體動因如下：  • 傳承延伸：品牌根植於美國“華盛頓黃金牧草”的百年家族種植傳統，早期為世界級賽馬提供專業牧草，創立初衷是將這一頂級品質的牧草資源，從專業馬場直接延伸至普通家庭寵物的餐桌，打破“高端牧草僅服務大型競技動物”的壁壘。  • 體驗升級：洞察到傳統乾草存在體積臃腫、粉塵多、不易存儲、營養流失等痛點，通過研發“雙壓縮（Double Compression）”工藝，以工業化創新解決行業共性痛點，實現“省空間、保新鮮、護健康”的三重價值。  • 使命驅動：以“家族傳承，寵物營養”為核心使命，將科學種植與家庭養寵需求結合，致力於為小寵（兔、豚鼠等）提供比肩賽馬級別的安全、優質口糧。', '臻萃品質；創新工藝；人本初心', NULL, NULL, '維度 Every Hay 優勢 競品（如 Standlee/Anderson）特點  工藝壁壘 獨家雙壓縮工藝，是行業內率先將該技術大規模應用於寵物牧草的品牌，實現“緊實存儲+低粉塵養護”雙重體驗，競品多以常規壓縮或散裝為主。 傳統競品多采用單一壓縮工藝，產品體積大、粉塵較高，存儲和使用體驗相對粗糙。  場景適配 精准定位家庭小寵（兔、豚鼠、龍貓）市場，產品規格、包裝設計（如“麵包狀”草捆）更貼合家庭收納與日常餵食場景。 多數競品產品線偏向馬場、農場等大型養殖場景，產品規格偏大、包裝粗獷，對家庭養寵人群的適配度低。  信任背書 兼具“賽馬級原料標準”與“寵物專用安全認證”雙重背書，既具備高端農業的技術底蘊，又貼合寵物營養的專業需求。 傳統競品要麼側重農業生產（缺乏寵物營養細分背書），要麼側重寵物功能（缺乏高端種植底蘊），價值維度較單一。', '市場教育成本高：“雙壓縮工藝”屬於行業創新概念，普通消費者對其價值（如低粉塵、高營養）的認知仍需培育，相比“有機/無添加”等傳統賣點，教育週期更長。  • 價格帶競爭壓力：相較於Border Valley等主打性價比的競品，Every Hay的高端定位導致價格彈性較小，在價格敏感的下沈市場拓展難度大；同時面臨宜家等跨界家居品牌通過聯名切入寵物用品領域的潛在衝擊。  • 渠道覆蓋局限：目前主要依賴Instagram等社媒渠道與高端養寵社群，線下商超、寵物連鎖店等大眾渠道的覆蓋密度不足，觸達普通消費者的路徑較窄。  • 品類依賴度高：核心增長依賴“雙壓縮乾草”單一品類，若後續競品快速模仿該工藝，或寵物主糧品牌推出配套“鮮草/濕草”產品，易陷入同質化競爭。', NULL, '寵物用品', 'Signature Timothy Hay 18OZ (510g)', '官網', 'HKD280', '香港養兔子的家庭', '溫暖親切', NULL, '抹茶綠', '#6B8F5A', '1EVGb-qyn0Yjjzs2jBcJO9TQM_eMBhkaW', '1nM6SCL7L9AyqNNCETo5NxEtuf19Vu1Aw', '生成失敗，請重試', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO brand_applications ("id", "status", "submittedAt", "email", "name", "website", "fb", "ig", "xiaohongshu", "douyin", "wechat", "socialOther", "contact", "phone", "story", "values", "competitors", "competitorUrls", "pros", "cons", "misc", "category", "products", "platforms", "price", "audience", "style", "ref", "color", "colorHex", "photoFolder", "videoFolder", "soulBook", "reviewNote", "kolType", "kolUrl1", "kolUrl2", "ownerName", "ownerStory", "ownerTone", "kolGenerated", "kolGenError", "desiredPlan") VALUES ('brand_1779369521166', 'approved', '2026-05-21T13:18:41.166Z', 'cyndi04592@gmail.com', 'PROTEX', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '稻宮', '+886 0000000000', '近年日本登山與郊區熊害事件頻傳,2019 到 2025 年熊出沒暴增近 9 倍,「熊」甚至被選為 2025 年度漢字。我們想做一支讓登山客、露營者、農林作業人員能安心隨身攜帶的正規防熊噴霧。採用高濃度辣椒素配方,在遇到熊時爭取寶貴的逃生時間,守護每一位戶外活動者的生命安全。', '戶外安全、專業防護、安心隨行', '熊一目散(日本國產)、Counter Assault、Frontiersman、UDAP', 'https://e-mot.co.jp/counter-assault/?srsltid=AfmBOooBs6HYRawyuPG1gfuU2P76hOTY3k_R8FvQX_JQ372nsAojIWeL  https://www.sabreoutdoor.jp/', '日本規格設計、辣椒素濃度 2.00%、安全插銷防誤觸、180mL 輕便隨身好攜帶、噴射距離達 4 到 7 公尺,在市面充斥仿冒品與對人用噴霧冒充的環境下,主打正規足量的防熊效果。', '台灣消費者對防熊噴霧認知度低、主力市場在日本、單價高於一般防身噴霧、需要教育市場辨別正規品與仿冒品的差異。', NULL, '運動休閒', 'PROTEX 防熊噴霧 180mL', '官網', 1280, '登山客、露營玩家、農林作業人員、戶外運動愛好者、赴日旅遊登山者', '國際商務', '黑底配螢光黃,硬派戶外裝備感,類似 The North Face、Garmin 的專業戶外品牌調性,強調安全與專業可靠。', '珊瑚橙', '#FF6B6B', '1x7BIEufLRV_Oy7IcDIm9tRy2KxUrTNMg', '1uor2RfBGaTPKka8pRm-6WTVG7FkiGvHB', '# PROTEX 品牌靈魂書  ## 1. 品牌定位宣言 **「野外探險，生命至上——PROTEX 正規防熊，專業守護每一次戶外冒險」**  ## 2. 品牌靈魂  在大自然面前，我們敬畏但不退縮。PROTEX 誕生於對戶外安全的深度關注，面對日本熊害事件激增的嚴峻現實，我們堅持以最高規格的防護標準，研發真正有效的防熊噴霧。  我們相信，每一位熱愛山林的探險者都值得擁有最可靠的安全防護。透過日本規格的專業設計與 2.00% 高濃度辣椒素配方，PROTEX 不只是一瓶噴霧，更是你在野外的生命守護者。  專業、可靠、安心——這是 PROTEX 對每位戶外愛好者的承諾，讓你在面對未知危險時，能夠從容應對，安全歸來。  ## 3. 目標受眾畫像  ### 主要受眾：專業登山客 (30-50歲) - **背景**：有多年登山經驗，經常前往中高海拔山區 - **痛點**：擔心遭遇野生動物攻擊，市面防身噴霧效果存疑 - **需求**：尋找專業級防護裝備，願意投資安全設備 - **行為**：活躍於登山社群，重視裝備品質與安全性  ### 次要受眾：露營愛好者 (25-45歲) - **背景**：假日喜愛戶外露營，帶家人體驗自然 - **痛點**：擔心露營地點的安全性，尤其是野生動物威脅 - **需求**：輕便好攜帶的安全防護工具 - **行為**：關注露營資訊，注重家人安全  ### 潛在受眾：赴日登山旅客 (25-55歲) - **背景**：計劃前往日本登山旅遊，關注當地熊害新聞 - **痛點**：對日本山區安全狀況感到擔憂 - **需求**：符合日本標準的正規防護用品 - **行為**：積極搜尋日本旅遊安全資訊  ## 4. 廣告文案風格指南  ### 語調特色 - **專業權威**：使用技術數據與規格資訊建立可信度 - **安全至上**：強調生命安全的重要性，語氣嚴肅但不恐嚇 - **簡潔有力**：避免冗長說明，重點突出關鍵資訊 - **教育性質**：提供正確的防熊知識與產品認知  ### 用詞偏好 ✅ 使用：專業防護、日本規格、高濃度配方、安全距離、正規品質 ❌ 避免：便宜、一般、普通、大概、可能  ### 句型結構 - 多用短句，節奏明快 - 數據化表達（2.00%濃度、4-7公尺射程） - 場景化描述（登山路上、露營夜晚）  ## 5. 核心廣告主張  ### 主張一：專業規格防護 **「日本規格設計 × 2.00% 高濃度辣椒素，專業級防熊效果」** - 強調技術規格與專業標準 - 適用於重視裝備品質的專業用戶  ### 主張二：安全距離守護 **「4-7公尺安全距離，關鍵時刻爭取逃生時間」** - 突出實用性與生存價值 - 針對實際使用情境的需求  ### 主張三：正規品質保證 **「拒絕仿冒，堅持正規——真正有效的防熊防護」** - 強調品質差異化 - 教育市場識別正規產品  ## 6. 建議 Hashtag  ### 中文標籤 1. #防熊噴霧 2. #戶外安全 3. #登山裝備 4. #露營必備 5. #日本規格  ### 英文標籤 6. #BearSpray 7. #OutdoorSafety 8. #HikingSafety 9. #CampingGear 10. #PROTEX防熊  ## 7. 競爭差異化重點  ### 產品差異化 - **日本規格標準**：針對日本熊害問題專門設計 - **2.00% 辣椒素濃度**：明確標示有效成分含量 - **180mL 輕便設計**：平衡效果與攜帶便利性 - **安全插銷設計**：防止意外觸發的專業設計  ### 市場定位差異 - **正規品牌承諾**：在仿冒品氾濫市場中建立信任 - **專業教育導向**：不只賣產品，更提供正確知識 - **目標市場聚焦**：專注戶外專業用戶，非一般防身市場  ### 傳播策略差異 - **數據化溝通**：用具體規格建立專業形象 - **場景化行銷**：結合實際戶外活動情境 - **社群教育**：透過專業內容建立品牌權威性  ---  **聯絡資訊** 品牌諮詢：稻宮 +886 0000000000', NULL, 'none', NULL, NULL, NULL, NULL, NULL, 'not_requested', NULL, NULL);
INSERT INTO brand_applications ("id", "status", "submittedAt", "email", "name", "website", "fb", "ig", "xiaohongshu", "douyin", "wechat", "socialOther", "contact", "phone", "story", "values", "competitors", "competitorUrls", "pros", "cons", "misc", "category", "products", "platforms", "price", "audience", "style", "ref", "color", "colorHex", "photoFolder", "videoFolder", "soulBook", "reviewNote", "kolType", "kolUrl1", "kolUrl2", "ownerName", "ownerStory", "ownerTone", "kolGenerated", "kolGenError", "desiredPlan") VALUES ('brand_1781493332858', 'rejected', '2026-06-15T03:15:32.858Z', 'cyndi04592@gmail.com', '示範品牌', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '王曉華', '+886 0912555666', '示範品牌靠這款系統更懶惰，讓更多的人能用這款系統!!', '智能、輕鬆、簡單', 'GPT', NULL, '錢比多、算力很多、頂尖企業', '沒錢、需要更多的用戶、阿公阿罵都會用', NULL, '設計/創意服務', '圖文設計系統 廣告分析監控系統 KOL數字人系統', '官網、私訊/Line下單、線下活動/課程', 60000, '品牌企業主', '專業質感', NULL, '夜幕深藍', '#1B2A4A', '1ewRMzjWH5Hg9rcsx_guc1e_Ph5w-KhK1', '1S5a-vtGWM9YJJltPlVVKf5uz8YXeyHE2', '# 示範品牌 - 品牌靈魂書  ## 1. 品牌定位宣言 **「讓智能設計成為每個品牌的超能力」**  ---  ## 2. 品牌靈魂  我們相信，最好的科技應該是無感的科技。  當設計變得智能、操作變得輕鬆、創意變得簡單，品牌主就能專注在最重要的事情上——與客戶建立深度連結。  我們不只是提供工具，更是提供一種全新的工作方式，讓每個品牌都能擁有頂尖企業級的設計與行銷能力。  在這個快速變化的數位時代，我們是您最值得信賴的智能夥伴。  ---  ## 3. 目標受眾畫像  ### 主要客群：中小型品牌企業主 - **年齡**：35-50歲 - **職位**：創辦人、行銷總監、品牌經理 - **公司規模**：10-200人的成長型企業  ### 核心痛點： 1. **設計資源有限**：沒有專業設計團隊，外包成本高且溝通困難 2. **行銷效率低下**：廣告投放效果難以追蹤，ROI不透明 3. **人力成本壓力**：想要專業品質但預算有限，需要更有效率的解決方案 4. **技術門檻高**：市面上工具太複雜，學習成本高，團隊接受度低 5. **競爭壓力大**：需要快速產出高質量內容以保持市場競爭力  ### 心理特徵： - 重視實用性與投資回報率 - 希望保持品牌專業形象 - 追求效率但不願妥協品質 - 對新技術保持開放但謹慎的態度  ---  ## 4. 廣告文案風格指南  ### 語調特色： - **專業而不冷漠**：使用專業術語但保持親切 - **簡潔有力**：避免冗長描述，直指核心價值 - **解決方案導向**：專注於解決客戶問題，而非炫耀技術  ### 文案公式： **痛點識別 + 解決方案 + 具體效益 + 行動呼籲**  ### 常用詞彙： - 正面詞彙：智能、高效、專業、簡單、強大、突破 - 避免詞彙：複雜、困難、昂貴、學習、技術門檻  ### 句式偏好： - 多使用肯定句 - 適度運用問句引起共鳴 - 數據化描述效果  ---  ## 5. 核心廣告主張  ### 方向一：效率革命 **「30秒完成專業級設計，讓創意不再等待」** - 強調操作簡單、快速出圖 - 適用於：功能介紹型廣告  ### 方向二：成本優化 **「一套系統＝設計師＋數據師＋KOL經紀，企業級服務不再遙不可及」** - 強調性價比與綜合價值 - 適用於：價格敏感型客群  ### 方向三：競爭優勢 **「當競爭對手還在手工作業，你已經進入AI時代」** - 強調技術領先與市場差異化 - 適用於：追求創新的企業主  ---  ## 6. 建議Hashtag  ### 中文標籤： 1. #智能設計系統 2. #品牌行銷利器 3. #AI設計工具 4. #數位行銷自動化 5. #企業效率提升  ### 英文標籤： 6. #SmartDesign 7. #BrandingTech 8. #MarketingAI 9. #DesignEfficiency 10. #BusinessGrowth  ---  ## 7. 競爭差異化重點  ### VS GPT等通用AI工具： ✅ **專業定制化**：針對品牌設計與行銷需求深度優化 ✅ **整合性解決方案**：設計+分析+KOL管理一站式服務 ✅ **本土化優勢**：更懂台灣市場與中文創意需求  ### 核心競爭優勢： 1. **技術實力**：頂尖企業級算力支撐，處理速度更快 2. **資源整合**：豐富的設計素材庫與KOL資源網絡 3. **服務深度**：不只是工具提供商，更是數位轉型夥伴 4. **在地服務**：中文客服團隊，了解本土商業文化  ### 差異化溝通重點： - 「我們不是萬能的AI，但我們是最懂品牌的AI」 - 「選擇通用工具還是專業解決方案？」 - 「同樣的預算，更專業的結果」  ---  **聯絡窗口**：王曉華 +886 0912555666 **品牌主色**：#1B2A4A **最後更新**：2024年', NULL, 'none', NULL, NULL, NULL, NULL, NULL, 'not_requested', NULL, NULL);
