INSERT INTO delivers ("id", "brand", "product", "hookScript", "coreScript", "ctaScript", "photoName", "photoUrl", "videoName", "videoUrl", "status", "createdAt") VALUES ('AD001', 'cf', '吸入式捕蚊器 UC-700', '每晚被蚊子叮到睡不著？', '巧福UC-700吸入式捕蚊器，運用物理風扇原理直接吸入蚊蟲，完全無毒無味無化學成分。讓寶寶在最安全的環境下一覺到天亮，媽媽也能安心休息不用半夜起來趕蚊子。', '守護全家安心睡眠，立即選購', '013042790.jpg', 'https://drive.google.com/file/d/15NyscmwWBg5m4o3DC1FO5ELJyhRYf-rn/view?usp=drivesdk', NULL, NULL, '素材已備妥', '2026-03-30T09:04:40.734Z');
INSERT INTO delivers ("id", "brand", "product", "hookScript", "coreScript", "ctaScript", "photoName", "photoUrl", "videoName", "videoUrl", "status", "createdAt") VALUES ('AD001', 'la', '無鋼圈內衣', '當媽後每天被鋼圈勒到快不能呼吸', '姐妹們，我懂那種痛苦！以前穿有鋼圈內衣，做家事到一半就開始勒得慌，晚上回家第一件事就是把內衣脫掉。  直到遇見LACEZ無鋼圈內衣，才知道原來內衣可以這麼舒服！我們是台灣MIT工廠直售，連那些知名品牌都找我們代工，但他們賣妳3000，我們只要990。  真正好的內衣不是要很貴，而是要讓妳從早穿到晚都忘記它的存在。無鋼圈設計完全不勒，親膚面料連敏感肌都能安心穿，重點是蕾絲細節依然很美，不會因為舒適就犧牲女人味。  很多客人都說：「早知道就不用忍受那麼多年的不舒服了！」姐妹，妳值得穿真正好的內衣，不用再委屈自己了。', '點進來讓自己舒服一整天', NULL, NULL, NULL, NULL, '缺素材', '2026-04-06T12:03:00.146Z');
INSERT INTO delivers ("id", "brand", "product", "hookScript", "coreScript", "ctaScript", "photoName", "photoUrl", "videoName", "videoUrl", "status", "createdAt") VALUES ('AD001', 'la', '蕾絲性感內衣', '妳花千元買的內衣其實工廠價只要三百', '姊妹們真的不要再當冤大頭了！ 我們LACEZ就是那個幫大牌代工的台灣工廠 妳在百貨公司花1200買的精品內衣 其實就是我們做的，成本才300多  現在我們決定直接賣給妳們 同樣的MIT精品質感、同樣的法式蕾絲工藝 但價格直接砍到工廠價 因為沒有中間商賺差價，妳省的錢可以多買好幾套  穿過的姊妹都說質感完全不輸專櫃貨 無鋼圈設計超舒適，蕾絲細節超精緻 重點是價格讓學生族群也能輕鬆入手 好內衣真的不用花大錢，選對工廠直售就對了', '工廠價優惠最後三天，手刀下單', '021014853.jpg', 'https://drive.google.com/file/d/1XBSz2HK5UH-ZvXcHR54Biu2ir3LOqWac/view?usp=drivesdk', NULL, NULL, '素材已備妥', '2026-04-06T14:22:46.854Z');
INSERT INTO delivers ("id", "brand", "product", "hookScript", "coreScript", "ctaScript", "photoName", "photoUrl", "videoName", "videoUrl", "status", "createdAt") VALUES ('AD001', 'ka', '200小時瑜珈師資培訓班', '從上班族到國際認證瑜珈老師只需200小時', '每天久坐8小時，肩頸痠痛、腰背緊繃已經成為你的日常？  空瑪那200小時瑜珈師資培訓，不只幫你解決身體問題，更開啟人生全新可能！  🌟 宸甄老師親自授課，印度YAI+美國RYT雙重國際認證 🌟 融合解剖學、阿育吠陀、中醫12經絡完整系統 🌟 從學員到專業師資的完美蛻變  這不只是瑜珈課程，是你重新定義人生的起點。當別人還在抱怨工作壓力時，你已經擁有療癒自己和他人的專業能力。  國際認證加持，讓你的專業被全世界看見！', '立即報名開啟瑜珈師資之路', NULL, NULL, NULL, NULL, '缺素材', '2026-04-06T14:27:53.147Z');
INSERT INTO delivers ("id", "brand", "product", "hookScript", "coreScript", "ctaScript", "photoName", "photoUrl", "videoName", "videoUrl", "status", "createdAt") VALUES ('AD001', 'cf', '吸入式捕蚊器 UC-700', '半夜蚊子嗡嗡叫，寶寶被咬滿身包怎麼辦', '傳統殺蟲劑有毒又有味，噴了擔心寶寶吸入有害物質 巧福UC-700吸入式捕蚊器，純物理捕蚊零化學 利用風扇氣流將蚊子吸入，自然風乾無毒無味 靜音設計不吵睡眠，一鍵開啟整夜守護 讓媽媽安心，給寶寶最純淨的睡眠環境 不用擦藥膏，不用點蚊香，物理捕蚊最安全', '立即下單守護寶寶安心睡眠', NULL, NULL, NULL, NULL, '缺素材', '2026-04-08T20:38:48.967Z');
