DROP TABLE IF EXISTS bits;
CREATE TABLE bits ("email" TEXT, "balance" TEXT, "plan" TEXT, "periodEnd" TEXT, "updatedAt" TEXT, "monthlyBits" TEXT, "monthlyBalance" TEXT, "extraBalance" TEXT, "subEnd" TEXT);
DROP TABLE IF EXISTS brand_applications;
CREATE TABLE brand_applications ("id" TEXT, "status" TEXT, "submittedAt" TEXT, "email" TEXT, "name" TEXT, "website" TEXT, "fb" TEXT, "ig" TEXT, "xiaohongshu" TEXT, "douyin" TEXT, "wechat" TEXT, "socialOther" TEXT, "contact" TEXT, "phone" TEXT, "story" TEXT, "values" TEXT, "competitors" TEXT, "competitorUrls" TEXT, "pros" TEXT, "cons" TEXT, "misc" TEXT, "category" TEXT, "products" TEXT, "platforms" TEXT, "price" TEXT, "audience" TEXT, "style" TEXT, "ref" TEXT, "color" TEXT, "colorHex" TEXT, "photoFolder" TEXT, "videoFolder" TEXT, "soulBook" TEXT, "reviewNote" TEXT, "kolType" TEXT, "kolUrl1" TEXT, "kolUrl2" TEXT, "ownerName" TEXT, "ownerStory" TEXT, "ownerTone" TEXT, "kolGenerated" TEXT, "kolGenError" TEXT, "desiredPlan" TEXT);
DROP TABLE IF EXISTS pending_payments;
CREATE TABLE pending_payments ("email" TEXT, "brandId" TEXT, "brandName" TEXT, "desiredPlan" TEXT, "status" TEXT, "approvedAt" TEXT);
DROP TABLE IF EXISTS delivers;
CREATE TABLE delivers ("id" TEXT, "brand" TEXT, "product" TEXT, "hookScript" TEXT, "coreScript" TEXT, "ctaScript" TEXT, "photoName" TEXT, "photoUrl" TEXT, "videoName" TEXT, "videoUrl" TEXT, "status" TEXT, "createdAt" TEXT);
DROP TABLE IF EXISTS memory;
CREATE TABLE memory ("id" TEXT, "timestamp" TEXT, "brandId" TEXT, "productId" TEXT, "brandName" TEXT, "productName" TEXT, "hookMethod" TEXT, "hookScript" TEXT, "coreType" TEXT, "ctaScript" TEXT, "score" REAL, "adId" TEXT);
